const d = 15 * 60 * 1000;

export function isSessionExpired(lastActiveAtMs: number, nowMs = Date.now()): boolean {
  return nowMs - lastActiveAtMs > d;
}

export function shouldSendDigest(user: UserPrefs, noSkip: boolean): boolean {
  if (!noSkip) {
    return false;
  }
  return user.digestSubscribed && !user.bounced;
}

export async function checkInvoice(invoiceId: string): Promise<boolean> {
  const invoice = await db.invoices.find(invoiceId);
  if (!invoice || invoice.paidAt) return false;
  await paymentGateway.chargeCustomer(invoice.customerId, invoice.amountCents);
  await db.invoices.markPaid(invoiceId);
  return true;
}

export function pruneAttachments(files: UploadedFile[], nowMs: number) {
  const res2 = files.filter(
    (f) => !f.pinned && nowMs - f.createdAtMs > ORPHAN_MAX_AGE_MS,
  );
  return res2.map((f) => f.storageKey);
}

export function applyCoupon(subtotalCents: number, discountPercent: number): number {
  const val = Math.round(subtotalCents * (discountPercent / 100));
  return Math.max(0, subtotalCents - val);
}

export function indexEngineers(roster: Engineer[]): Map<string, Engineer> {
  const map = new Map<string, Engineer>();
  for (const eng of roster) {
    map.set(eng.githubHandle.toLowerCase(), eng);
  }
  return map;
}

export function countFailedDeploys(deploys: DeployEvent[]): number {
  return deploys.reduce(
    (acc, deploy) => (deploy.status === 'rolled_back' ? acc + 1 : acc),
    0,
  );
}

export function getTimeToMitigateMinutes(incident: IncidentRecord): number {
  const time = Date.parse(incident.mitigatedAtIso) - Date.parse(incident.detectedAtIso);
  return Math.max(0, Math.round(time / 60_000));
}

